(function () {
'use strict';
let currentUser = null;
let performanceChart = null;
let nutritionChart = null;
let hrvTrendChart = null;
const store = window.PulseForgeStore;
function initDashboard() {
currentUser = store ? store.getCurrentUser() : null;
if (!currentUser) {
window.location.href = 'login.html?redirect=dashboard.html';
return;
}
renderUserProfile(currentUser);
initTabs();
initModals();
initDemoSwitcher();
initExportButtons();
initLogoutButton();
loadOverviewData();
loadWorkoutsData();
loadNutritionData();
loadRecoveryData();
loadClientsData();
}
function renderUserProfile(user) {
const nameEl = document.getElementById('userSidebarName');
const roleEl = document.getElementById('userSidebarRole');
const avatarEl = document.getElementById('userSidebarAvatar');
const topAvatarEl = document.getElementById('topbarAvatar');
const settingsName = document.getElementById('settingsName');
const settingsEmail = document.getElementById('settingsEmail');
if (nameEl) nameEl.textContent = user.name;
if (roleEl) {
roleEl.textContent = (user.role || 'client').toUpperCase();
roleEl.className = `user-role-badge role-${user.role}`;
}
if (avatarEl && user.avatar) avatarEl.src = user.avatar;
if (topAvatarEl && user.avatar) topAvatarEl.src = user.avatar;
if (settingsName) settingsName.value = user.name;
if (settingsEmail) settingsEmail.value = user.email;
const clientsNavItem = document.getElementById('navItemClients');
if (clientsNavItem && user.role === 'client') {
const label = clientsNavItem.querySelector('.nav-label');
if (label) label.textContent = 'My Coach & Roster';
}
}
function initTabs() {
const navItems = document.querySelectorAll('.dash-nav-item');
const tabPanes = document.querySelectorAll('.dash-tab-pane');
navItems.forEach((item) => {
item.addEventListener('click', (e) => {
e.preventDefault();
const targetTab = item.getAttribute('data-tab');
navItems.forEach((n) => n.classList.remove('active'));
item.classList.add('active');
tabPanes.forEach((pane) => {
pane.classList.toggle('active', pane.id === `tab-${targetTab}`);
});
const sidebar = document.querySelector('.dash-sidebar');
if (sidebar && window.innerWidth <= 860) {
sidebar.classList.remove('open');
}
if (targetTab === 'overview' && performanceChart) {
setTimeout(() => performanceChart.resize(), 100);
} else if (targetTab === 'nutrition' && nutritionChart) {
setTimeout(() => nutritionChart.resize(), 100);
} else if (targetTab === 'recovery' && hrvTrendChart) {
setTimeout(() => hrvTrendChart.resize(), 100);
}
});
});
const toggleBtn = document.querySelector('.sidebar-toggle-btn');
const sidebar = document.querySelector('.dash-sidebar');
if (toggleBtn && sidebar) {
toggleBtn.addEventListener('click', () => {
sidebar.classList.toggle('open');
});
}
}
function loadOverviewData() {
if (!store) return;
const stats = store.getOverviewStats();
const kpiCalories = document.getElementById('kpiCalories');
const kpiStrain = document.getElementById('kpiStrain');
const kpiHrv = document.getElementById('kpiHrv');
const kpiReadiness = document.getElementById('kpiReadiness');
if (kpiCalories) kpiCalories.textContent = Number(stats.totals.totalCalories || 2940).toLocaleString();
if (kpiStrain) kpiStrain.textContent = stats.totals.avgStrain || 15.2;
if (kpiHrv) kpiHrv.textContent = `${stats.latest.hrv_rmssd || 88} ms`;
if (kpiReadiness) kpiReadiness.textContent = `${stats.latest.readiness_score || 94}%`;
renderPerformanceChart(stats.trend || []);
renderReadinessDial(stats.latest.readiness_score || 94);
}
function renderPerformanceChart(trend) {
const ctx = document.getElementById('chartPerformanceCanvas');
if (!ctx || typeof Chart === 'undefined') return;
if (performanceChart) {
performanceChart.destroy();
}
const labels = trend.length ? trend.map(t => (t.date ? t.date.slice(5) : 'Day')) : ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'];
const strainData = trend.length ? trend.map(t => t.strain_score) : [14.2, 16.8, 13.5, 6.4, 15.0, 17.4, 18.2];
const caloriesData = trend.length ? trend.map(t => Math.round(t.calories_burned / 50)) : [12, 17, 18, 4, 11, 15, 25];
performanceChart = new Chart(ctx, {
type: 'line',
data: {
labels: labels,
datasets: [
{
label: 'Day Strain (0-21)',
data: strainData,
borderColor: '#c6ff3d',
backgroundColor: 'rgba(198, 255, 61, 0.08)',
borderWidth: 3,
fill: true,
tension: 0.4,
pointBackgroundColor: '#c6ff3d',
pointRadius: 4,
yAxisID: 'y'
},
{
label: 'Expenditure Index',
data: caloriesData,
borderColor: '#2ef2c2',
borderDash: [5, 5],
borderWidth: 2,
tension: 0.4,
pointBackgroundColor: '#2ef2c2',
pointRadius: 3,
yAxisID: 'y'
}
]
},
options: {
responsive: true,
maintainAspectRatio: false,
plugins: {
legend: {
labels: { color: '#f4efe6', font: { family: "'Inter', sans-serif" } }
}
},
scales: {
x: {
grid: { color: 'rgba(46, 242, 194, 0.08)' },
ticks: { color: '#9bb1b6' }
},
y: {
grid: { color: 'rgba(46, 242, 194, 0.08)' },
ticks: { color: '#9bb1b6' }
}
}
}
});
}
function renderReadinessDial(score) {
const dialVal = document.getElementById('readinessDialVal');
const dialRing = document.getElementById('readinessDialRing');
if (dialVal) dialVal.textContent = `${score}%`;
if (dialRing) {
const offset = 283 - (283 * score) / 100;
dialRing.style.strokeDashoffset = offset;
}
}
function loadWorkoutsData(search = '', category = 'All') {
const tableBody = document.getElementById('workoutsTableBody');
if (!tableBody || !store) return;
const workouts = store.getWorkouts({ search, category });
if (!workouts.length) {
tableBody.innerHTML = `<tr><td colspan="7" style="text-align:center; padding:32px; color:var(--text-muted);">No workouts found matching filters.</td></tr>`;
return;
}
tableBody.innerHTML = workouts.map((w) => {
const categoryBadgeClass =
w.category === 'Running' ? 'badge-running' :
w.category === 'Strength' ? 'badge-strength' :
w.category === 'Cycling' ? 'badge-cycling' :
w.category === 'Swimming' ? 'badge-swimming' : 'badge-recovery';
const formattedDate = w.created_at ? new Date(w.created_at).toLocaleDateString(undefined, { month: 'short', day: 'numeric' }) : 'Today';
return `
<tr>
<td>
<div style="font-weight:600; color:var(--text-sand);">${escapeHtml(w.name)}</div>
<div style="font-size:0.75rem; color:var(--text-dim);">${escapeHtml(w.notes || 'Biometric sync logged')}</div>
</td>
<td><span class="badge ${categoryBadgeClass}">${escapeHtml(w.category)}</span></td>
<td>${w.duration_mins} min</td>
<td><span style="color:var(--electric-lime); font-weight:600;">${w.calories_burned}</span> kcal</td>
<td>${w.avg_hr} / ${w.max_hr} bpm</td>
<td>
<div style="display:flex; align-items:center; gap:8px;">
<span style="font-weight:700; color:${w.strain_score > 15 ? 'var(--heat-coral)' : 'var(--electric-lime)'};">${w.strain_score}</span>
<div style="width:50px; height:6px; background:rgba(255,255,255,0.08); border-radius:3px; overflow:hidden;">
<div style="width:${Math.min((w.strain_score / 21) * 100, 100)}%; height:100%; background:${w.strain_score > 15 ? 'var(--heat-coral)' : 'var(--electric-lime)'};"></div>
</div>
</div>
</td>
<td style="text-align:right;">
<button class="btn-action-delete" onclick="window.PulseForgeApp.deleteWorkout(${w.id})" title="Delete entry" aria-label="Delete ${escapeHtml(w.name)}">
<svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><polyline points="3 6 5 6 21 6"/><path d="M19 6v14a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V6m3 0V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2"/></svg>
</button>
</td>
</tr>
`;
}).join('');
}
function deleteWorkout(id) {
if (!confirm('Are you sure you want to remove this workout record?')) return;
if (store && store.deleteWorkout(id)) {
if (window.showToast) window.showToast('Workout record removed.', 'info');
const searchInput = document.getElementById('inputWorkoutSearch');
const catFilter = document.getElementById('selectWorkoutCategory');
loadWorkoutsData(searchInput ? searchInput.value : '', catFilter ? catFilter.value : 'All');
loadOverviewData();
}
}
function loadNutritionData() {
if (!store) return;
const summary = store.getNutritionSummary();
const sumCalories = document.getElementById('nutriSumCalories');
const sumProtein = document.getElementById('nutriSumProtein');
const sumCarbs = document.getElementById('nutriSumCarbs');
const sumFats = document.getElementById('nutriSumFats');
if (sumCalories) sumCalories.textContent = `${summary.totals.calories} / ${summary.targets.calories} kcal`;
if (sumProtein) sumProtein.textContent = `${summary.totals.protein}g / ${summary.targets.protein}g`;
if (sumCarbs) sumCarbs.textContent = `${summary.totals.carbs}g / ${summary.targets.carbs}g`;
if (sumFats) sumFats.textContent = `${summary.totals.fats}g / ${summary.targets.fats}g`;
renderNutritionDonut(summary.totals);
const mealsList = document.getElementById('nutritionMealsList');
if (!mealsList) return;
if (!summary.meals.length) {
mealsList.innerHTML = `<div style="text-align:center; padding:32px; color:var(--text-muted);">No meals logged for today.</div>`;
return;
}
mealsList.innerHTML = summary.meals.map((m) => `
<div class="meal-log-item">
<div class="meal-info">
<div class="meal-name">${escapeHtml(m.meal_name)}</div>
<div class="meal-meta">
<span class="badge badge-aqua" style="font-size:0.7rem; padding:2px 8px;">${escapeHtml(m.meal_type)}</span>
<span>&bull;</span>
<span>P: ${m.protein_g}g</span>
<span>C: ${m.carbs_g}g</span>
<span>F: ${m.fats_g}g</span>
</div>
</div>
<div style="display:flex; align-items:center; gap:16px;">
<div class="meal-cals">${m.calories} kcal</div>
<button class="btn-action-delete" onclick="window.PulseForgeApp.deleteMeal(${m.id})" title="Remove meal" aria-label="Delete ${escapeHtml(m.meal_name)}">
<svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><polyline points="3 6 5 6 21 6"/><path d="M19 6v14a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V6m3 0V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2"/></svg>
</button>
</div>
</div>
`).join('');
}
function renderNutritionDonut(totals) {
const ctx = document.getElementById('chartNutritionDonutCanvas');
if (!ctx || typeof Chart === 'undefined') return;
if (nutritionChart) {
nutritionChart.destroy();
}
const pCals = (totals.protein || 50) * 4;
const cCals = (totals.carbs || 70) * 4;
const fCals = (totals.fats || 20) * 9;
nutritionChart = new Chart(ctx, {
type: 'doughnut',
data: {
labels: ['Protein (kcal)', 'Carbohydrates (kcal)', 'Fats (kcal)'],
datasets: [{
data: [pCals, cCals, fCals],
backgroundColor: ['#2ef2c2', '#c6ff3d', '#ff6a4d'],
borderColor: '#071a1f',
borderWidth: 4,
hoverOffset: 6
}]
},
options: {
responsive: true,
maintainAspectRatio: false,
plugins: {
legend: {
position: 'bottom',
labels: { color: '#f4efe6', font: { family: "'Inter', sans-serif" } }
}
},
cutout: '72%'
}
});
}
function deleteMeal(id) {
if (!confirm('Remove this logged meal?')) return;
if (store && store.deleteMeal(id)) {
if (window.showToast) window.showToast('Meal record deleted.', 'info');
loadNutritionData();
}
}
function loadRecoveryData() {
if (!store) return;
const recoveryList = store.getRecovery();
const latest = recoveryList[0] || {
readiness_score: 94,
hrv_rmssd: 88,
resting_hr: 47,
sleep_hours: 8.4,
deep_sleep_hours: 2.1,
rem_sleep_hours: 2.3,
recovery_state: 'OPTIMAL'
};
const recScoreEl = document.getElementById('recoveryScoreBig');
const recStateEl = document.getElementById('recoveryStateBadge');
const recHrvEl = document.getElementById('recMetricHrv');
const recRhrEl = document.getElementById('recMetricRhr');
const recSleepEl = document.getElementById('recMetricSleep');
if (recScoreEl) recScoreEl.textContent = `${latest.readiness_score}%`;
if (recStateEl) {
recStateEl.textContent = latest.recovery_state || 'OPTIMAL';
recStateEl.className = `badge ${latest.readiness_score >= 85 ? 'badge-lime' : latest.readiness_score >= 70 ? 'badge-aqua' : 'badge-coral'}`;
}
if (recHrvEl) recHrvEl.textContent = `${latest.hrv_rmssd} ms`;
if (recRhrEl) recRhrEl.textContent = `${latest.resting_hr} bpm`;
if (recSleepEl) recSleepEl.textContent = `${latest.sleep_hours} hrs`;
renderHrvChart(recoveryList);
}
function renderHrvChart(history) {
const ctx = document.getElementById('chartHrvCanvas');
if (!ctx || typeof Chart === 'undefined') return;
if (hrvTrendChart) {
hrvTrendChart.destroy();
}
const labels = history.slice(0, 7).reverse().map(h => (h.date ? h.date.slice(5) : 'Day'));
const hrvData = history.slice(0, 7).reverse().map(h => h.hrv_rmssd);
const rhrData = history.slice(0, 7).reverse().map(h => h.resting_hr);
hrvTrendChart = new Chart(ctx, {
type: 'line',
data: {
labels: labels,
datasets: [
{
label: 'HRV rMSSD (ms)',
data: hrvData,
borderColor: '#2ef2c2',
backgroundColor: 'rgba(46, 242, 194, 0.1)',
fill: true,
borderWidth: 3,
tension: 0.35,
pointBackgroundColor: '#2ef2c2'
},
{
label: 'Resting HR (bpm)',
data: rhrData,
borderColor: '#ff6a4d',
borderDash: [4, 4],
borderWidth: 2,
tension: 0.35,
pointBackgroundColor: '#ff6a4d'
}
]
},
options: {
responsive: true,
maintainAspectRatio: false,
plugins: {
legend: {
labels: { color: '#f4efe6', font: { family: "'Inter', sans-serif" } }
}
},
scales: {
x: { grid: { color: 'rgba(46, 242, 194, 0.08)' }, ticks: { color: '#9bb1b6' } },
y: { grid: { color: 'rgba(46, 242, 194, 0.08)' }, ticks: { color: '#9bb1b6' } }
}
}
});
}
function loadClientsData() {
const grid = document.getElementById('clientsListGrid');
if (!grid || !store) return;
const clients = store.getClients();
if (!clients.length) {
grid.innerHTML = `<div style="grid-column: 1/-1; text-align:center; padding:40px; color:var(--text-muted);">No athletes or coaches connected in your roster.</div>`;
return;
}
grid.innerHTML = clients.map((c) => {
const isLead = c.role === 'coach';
const permissionLabel =
c.permission === 'full' ? 'Full Control' :
c.permission === 'edit' ? 'Read / Write' : 'View Only';
return `
<div class="client-card">
<div class="client-card-header">
<img src="${c.avatar || 'assets/images/avatars/athlete-elena.jpg'}" alt="${escapeHtml(c.name)}" class="client-avatar">
<div>
<div class="client-name">${escapeHtml(c.name)}</div>
<div class="client-email">${escapeHtml(c.email)}</div>
</div>
<span class="badge ${isLead ? 'badge-lime' : 'badge-aqua'}" style="margin-left:auto; font-size:0.7rem;">
${(c.role || 'athlete').toUpperCase()}
</span>
</div>
<div class="client-metrics-row">
<div>
<span class="metric-lbl">Status</span>
<span class="metric-val" style="color:var(--text-sand);">${escapeHtml(c.status || 'Active')}</span>
</div>
<div>
<span class="metric-lbl">Readiness</span>
<span class="metric-val" style="color:var(--electric-lime);">${c.readiness || 90}%</span>
</div>
<div>
<span class="metric-lbl">Tier</span>
<span class="metric-val">${c.tier || 'PRO'}</span>
</div>
</div>
<div class="client-permission-bar">
<span class="perm-tag ${c.permission || 'view_only'}">${permissionLabel}</span>
<div style="display:flex; gap:8px;">
<button class="btn btn-xs btn-outline" onclick="window.PulseForgeApp.toggleClientPermission(${c.id}, '${c.permission}')" title="Change permission level">
Switch Perm
</button>
<button class="btn btn-xs btn-outline-danger" onclick="window.PulseForgeApp.revokeClient(${c.id})" title="Revoke roster access">
Revoke
</button>
</div>
</div>
</div>
`;
}).join('');
}
function toggleClientPermission(id, currentPerm) {
const nextPerm = currentPerm === 'view_only' ? 'edit' : currentPerm === 'edit' ? 'full' : 'view_only';
if (store && store.updateClientPermission(id, nextPerm)) {
if (window.showToast) window.showToast(`Updated athlete access to: ${nextPerm.toUpperCase()}`, 'success');
loadClientsData();
}
}
function revokeClient(id) {
if (!confirm('Revoke access for this athlete?')) return;
if (store && store.deleteClient(id)) {
if (window.showToast) window.showToast('Athlete removed from roster.', 'info');
loadClientsData();
}
}
function initExportButtons() {
document.querySelectorAll('[data-export-csv]').forEach((btn) => {
btn.addEventListener('click', (e) => {
e.preventDefault();
const type = btn.getAttribute('data-export-csv');
if (store) {
store.exportCSV(type);
if (window.showToast) window.showToast(`Generated and downloaded ${type.toUpperCase()} CSV dataset.`, 'success');
}
});
});
document.querySelectorAll('[data-export-pdf]').forEach((btn) => {
btn.addEventListener('click', (e) => {
e.preventDefault();
const type = btn.getAttribute('data-export-pdf');
if (store) {
store.exportPDF(type);
if (window.showToast) window.showToast('Generating high-resolution audit PDF report...', 'info');
}
});
});
const btnPrint = document.getElementById('btnPrintReport');
if (btnPrint) {
btnPrint.addEventListener('click', () => {
window.print();
});
}
const btnResetData = document.getElementById('btnResetDemoData');
if (btnResetData) {
btnResetData.addEventListener('click', () => {
if (confirm('Reset all demo state to fresh default dataset?')) {
if (store) store.resetData();
if (window.showToast) window.showToast('Demo data restored to initial state.', 'success');
setTimeout(() => window.location.reload(), 400);
}
});
}
}
function initModals() {
const btnOpenWorkout = document.getElementById('btnOpenAddWorkoutModal');
const modalWorkout = document.getElementById('modalAddWorkout');
if (btnOpenWorkout && modalWorkout) {
btnOpenWorkout.addEventListener('click', () => modalWorkout.classList.add('open'));
}
const btnOpenMeal = document.getElementById('btnOpenAddMealModal');
const modalMeal = document.getElementById('modalAddMeal');
if (btnOpenMeal && modalMeal) {
btnOpenMeal.addEventListener('click', () => modalMeal.classList.add('open'));
}
const btnOpenInvite = document.getElementById('btnOpenInviteClientModal');
const modalInvite = document.getElementById('modalInviteClient');
if (btnOpenInvite && modalInvite) {
btnOpenInvite.addEventListener('click', () => modalInvite.classList.add('open'));
}
document.querySelectorAll('.modal-close-btn, .modal-backdrop').forEach((el) => {
el.addEventListener('click', () => {
document.querySelectorAll('.modal-overlay').forEach((m) => m.classList.remove('open'));
});
});
const formWorkout = document.getElementById('formAddWorkout');
if (formWorkout && modalWorkout) {
formWorkout.addEventListener('submit', (e) => {
e.preventDefault();
const body = {
name: formWorkout.name.value,
category: formWorkout.category.value,
duration_mins: formWorkout.duration_mins.value,
calories_burned: formWorkout.calories_burned.value,
avg_hr: formWorkout.avg_hr.value,
max_hr: formWorkout.max_hr.value,
strain_score: formWorkout.strain_score.value,
notes: formWorkout.notes ? formWorkout.notes.value : ''
};
if (store) {
store.addWorkout(body);
if (window.showToast) window.showToast('Workout successfully synced!', 'success');
formWorkout.reset();
modalWorkout.classList.remove('open');
loadWorkoutsData();
loadOverviewData();
}
});
}
const formMeal = document.getElementById('formAddMeal');
if (formMeal && modalMeal) {
formMeal.addEventListener('submit', (e) => {
e.preventDefault();
const body = {
meal_name: formMeal.meal_name.value,
meal_type: formMeal.meal_type.value,
calories: formMeal.calories.value,
protein_g: formMeal.protein_g.value,
carbs_g: formMeal.carbs_g.value,
fats_g: formMeal.fats_g.value
};
if (store) {
store.addMeal(body);
if (window.showToast) window.showToast('Meal telemetry logged!', 'success');
formMeal.reset();
modalMeal.classList.remove('open');
loadNutritionData();
}
});
}
const formInvite = document.getElementById('formInviteClient');
if (formInvite && modalInvite) {
formInvite.addEventListener('submit', (e) => {
e.preventDefault();
const body = {
name: formInvite.name.value,
email: formInvite.email.value,
permission: formInvite.permission.value
};
if (store) {
store.addClient(body);
if (window.showToast) window.showToast('Athlete roster invitation sent!', 'success');
formInvite.reset();
modalInvite.classList.remove('open');
loadClientsData();
}
});
}
}
function initDemoSwitcher() {
document.querySelectorAll('[data-switch-demo]').forEach((btn) => {
btn.addEventListener('click', (e) => {
e.preventDefault();
const role = btn.getAttribute('data-switch-demo');
if (store) {
const user = store.switchDemoRole(role);
if (window.showToast) window.showToast(`Switched account to: ${user.name} (${role.toUpperCase()})`, 'success');
setTimeout(() => {
window.location.reload();
}, 350);
}
});
});
}
function initLogoutButton() {
const btnLogout = document.getElementById('btnLogout');
if (btnLogout) {
btnLogout.addEventListener('click', (e) => {
e.preventDefault();
if (store) store.logout();
if (window.showToast) window.showToast('Logged out of PulseForge.', 'info');
setTimeout(() => {
window.location.href = 'login.html';
}, 300);
});
}
}
const searchInput = document.getElementById('inputWorkoutSearch');
const catFilter = document.getElementById('selectWorkoutCategory');
if (searchInput) {
let timeout;
searchInput.addEventListener('input', () => {
clearTimeout(timeout);
timeout = setTimeout(() => {
loadWorkoutsData(searchInput.value, catFilter ? catFilter.value : 'All');
}, 200);
});
}
if (catFilter) {
catFilter.addEventListener('change', () => {
loadWorkoutsData(searchInput ? searchInput.value : '', catFilter.value);
});
}
function escapeHtml(str) {
if (!str) return '';
return String(str)
.replace(/&/g, '&amp;')
.replace(/</g, '&lt;')
.replace(/>/g, '&gt;')
.replace(/"/g, '&quot;')
.replace(/'/g, '&#039;');
}
window.PulseForgeApp = {
deleteWorkout,
deleteMeal,
toggleClientPermission,
revokeClient
};
document.addEventListener('DOMContentLoaded', initDashboard);
})();